export interface VehicleData {
  /** TESLEMETRY-EXT */
  guiSettings: GuiSettings | undefined;
  chargeState: ChargeState | undefined;
  climateState: ClimateState | undefined;
  driveState:
    | DriveState
    | undefined;
  /** VehicleState carries the legacy vehicle-state surface  // TESLEMETRY-EXT */
  legacyVehicleState:
    | VehicleState
    | undefined;
  /** TESLEMETRY-EXT */
  vehicleConfig: VehicleConfig | undefined;
  locationState: LocationState | undefined;
  closuresState: ClosuresState | undefined;
  protoJsonVersion?:
    | number
    | undefined;
  /**
   * Each entry is an encoded CarServer.EncryptedData (car_server.proto), declared
   * as bytes because vehicle.proto cannot import car_server.proto.
   */
  encryptedData: Uint8Array[];
  uploadReason?:
    | string
    | undefined;
  /** TESLEMETRY-EXT */
  parkedAccessoryState: ParkedAccessoryState | undefined;
  chargeScheduleState: ChargeScheduleState | undefined;
  preconditioningScheduleState:
    | PreconditioningScheduleState
    | undefined;
  /** TESLEMETRY-EXT */
  sohState:
    | SohState
    | undefined;
  /** present on live vehicleDataSubscription pushes  // TESLEMETRY-EXT */
  vehicleState: CurrentVehicleState | undefined;
  tirePressureState: TirePressureState | undefined;
  mediaState: MediaState | undefined;
  mediaDetailState:
    | MediaDetailState
    | undefined;
  /** TESLEMETRY-EXT */
  vehicleDetailState: VehicleDetailState | undefined;
  softwareUpdateState: SoftwareUpdateState | undefined;
  parentalControlsState:
    | ParentalControlsState
    | undefined;
  /** TESLEMETRY-EXT */
  alertState:
    | AlertState
    | undefined;
  /** TESLEMETRY-EXT */
  lightShowState:
    | LightShowState
    | undefined;
  /** TESLEMETRY-EXT */
  vehicleImageState:
    | VehicleImageState
    | undefined;
  /** TESLEMETRY-EXT */
  suspensionState:
    | SuspensionState
    | undefined;
  /** TESLEMETRY-EXT */
  childPresenceDetectionState:
    | ChildPresenceDetectionState
    | undefined;
  /** TESLEMETRY-EXT */
  displayState:
    | DisplayState
    | undefined;
  /** TESLEMETRY-EXT UNCONFIRMED: not yet confirmed on a live vehicle */
  keepOnAccessoryPortsState:
    | KeepOnAccessoryPortsState
    | undefined;
  /**
   * Each entry is an encoded CarServer.PiiKeyResponse (car_server.proto), declared
   * as bytes because vehicle.proto cannot import car_server.proto.
   */
  piiKeyResponses: Uint8Array[];
  /** An encrypted envelope whose message type this repo does not publish. */
  wrappedKey: Uint8Array;
  supportsOptionalFields?: boolean | undefined;
}

